import React from 'react';
import { IProfitDetails } from '../../../core/Interface/profitDetailReport.interface';
import { ColumnDef } from '@tanstack/react-table';
import { useTranslation } from 'react-i18next';
import { Box } from '@mui/material';
import { getPriceFormat } from '../../../core/utils';

const useProfitDetailsReportColumns = (
  pageIndex: number,
  pageSize: number,
  currencyCode: string
) => {
  const { t } = useTranslation(['profit']);

  return [
    {
      accessorKey: 'sn',
      header: <div style={{ textAlign: 'justify' }}>#</div>,
      size: 50,
      cell: (cell) => {
        const serialNumber = pageIndex * pageSize + cell.row.index + 1;
        return <Box sx={{ textAlign: 'justify' }}>{serialNumber}</Box>;
      },
    },
    {
      accessorKey: 'product.code',
      header: t('profit:productCode'),
      size: 180,
    },
    {
      accessorKey: 'product.name',
      header: t('profit:productName'),
      size: 160,
    },
    {
      accessorKey: 'purchaseCost',
      header: () => <Box sx={{ textAlign: 'right' }}>{t('profit:cost')}</Box>,
      size: 200,
      cell: (cell) => {
        return (
          <Box sx={{ textAlign: 'right' }}>
            {getPriceFormat(cell.row.original.purchaseCost, currencyCode)}
          </Box>
        );
      },
    },
    {
      accessorKey: 'sellingPrice',
      header: () => (
        <Box sx={{ textAlign: 'right' }}>{t('profit:sellingPrice')}</Box>
      ),
      size: 200,
      cell: (cell) => {
        return (
          <Box sx={{ textAlign: 'right' }}>
            {getPriceFormat(cell.row.original.sellingPrice, currencyCode)}
          </Box>
        );
      },
    },
    {
      accessorKey: 'qty',
      header: () => (
        <Box sx={{ textAlign: 'center' }}>{t('profit:soldQty')}</Box>
      ),
      cell: (cell) => {
        return <Box sx={{ textAlign: 'center' }}>{cell.row.original.qty}</Box>;
      },
      size: 100,
    },
    {
      accessorKey: 'profit',
      header: () => <Box sx={{ textAlign: 'right' }}>{t('profit:profit')}</Box>,
      size: 200,
      cell: (cell) => {
        return (
          <Box sx={{ textAlign: 'right' }}>
            {getPriceFormat(cell.row.original.profit, currencyCode)}
          </Box>
        );
      },
    },
    {
      accessorKey: 'id',
    },
  ] as ColumnDef<IProfitDetails>[];
};

export default useProfitDetailsReportColumns;
